// Open a connection to the website
var http = require('http');
var url = 'https://example.com';
var options = {
  hostname: 'example.com',
  port: 443,
  path: '/',
  method: 'GET'
};

// Send a request to the website
var req = http.request(options, function(res) {
  // Read the response
  var data = '';
